UPDATE NOTICE_RECEIVE 
SET is_received = 1, confirm_time = NOW(), remind_count = 0
WHERE notice_id = #{noticeId} AND teacher_id = #{teacherId}

UPDATE NOTICE_RECEIVE 
SET is_todo = 1
WHERE notice_id = #{noticeId} AND teacher_id = #{teacherId}

UPDATE NOTICE_RECEIVE 
SET is_todo = 0
WHERE notice_id = #{noticeId} AND teacher_id = #{teacherId}

UPDATE NOTICE_RECEIVE 
SET is_received = 0, is_todo = 0
WHERE notice_id = #{noticeId}

mapper.select:
SELECT COUNT(*)
FROM NOTICE_RECEIVE nr
INNER JOIN NOTICE n ON nr.notice_id = n.notice_id
WHERE nr.teacher_id = #{teacherId}
  AND nr.is_todo = 1
  AND n.publisher_id != #{teacherId}
